from collections import defaultdict

eights_demo1 = [(1, 5), (1, 7), (6, 1), (6, 7), (10, 3), (11, 4), (13, 3)]

def point_in_rect(pt, rect):
    """Relaxed: point inside or on edge."""
    tr, tc = rect[0]
    br_r, br_c = rect[1]
    r, c = pt
    return tr <= r <= br_r and tc <= c <= br_c

# Build cell -> target mapping from demo 1
# This will be used as reference
