for r in range(len(demo1_in)):
    for c in range(len(demo1_in[0])):
        if demo1_in[r][c] != demo1_out[r][c]:
            cell_target_map[(r,c)] = demo1_out[r][c]

# Now apply to test grid
def predict_grid(grid):
    h, w = len(grid), len(grid[0])

    # Find all 8s
    eights = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]

    # Background value
    non_anchor = [grid[r][c] for r in range(h) for c in range(w) 
                  if grid[r][c] not in [1, 2, 6, 8]]
    background = max(set(non_anchor), key=non_anchor.count)

    # Create output with background
    result = [[background]*w for _ in range(h)]

    # Mark anchors
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in [1, 2, 6, 8]:
                result[r][c] = v

    # Apply rectangle filling
    for i in range(len(eights)):
        for j in range(i+1, len(eights)):
            r1, c1 = eights[i]
            r2, c2 = eights[j]

            tl_r, tc = min(r1, r2), min(c1, c2)
            br_r, br_c = max(r1, r2), max(c1, c2)

            # Need meaningful interior
            if br_r > tl_r and br_c > tc:
                for r in range(tl_r, br_r + 1):
                    for c in range(tc, br_c + 1):
                        # Skip anchor positions
                        if grid[r][c] in [1, 2, 6, 8]:
                            continue
                        if result[r][c] == background:
                            result[r][c] = 4

    # Handle special cases for cells near 8s
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != 8:
                continue

            # Check neighbors within distance 1
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue

                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if result[nr][nc] == background:
                            # Within distance 1 of 8 -> might become 7
                            dist = max(abs(dr), abs(dc))
                            if dist <= 1:
                                result[nr][nc] = 7

    return result

# Test
test1_pred = predict_grid(demo1_in_np)

print("Accuracy:", sum(1 for r in range(len(demo1_in)) for c in range(len(demo1_in[0])) 
                   if test1_pred[r][c] == demo1_out[r][c]), f"/{len(demo1_in)*len(demo1_in[0])}")

