def solve_arc_puzzle(grid_in):
    """
    Solve ARC puzzle based on patterns learned from demos.

    Rules:
    - Background is most common non-anchor value (excluding 1,2,6,8)
    - Anchor cells (1,2,6,8) stay unchanged
    - Cells strictly between two 8s in same ROW become 4 (interior fill)
    - If a cell is equidistant midpoint between two 8s, it becomes 7
    - Vertical fills also apply similarly

    The pattern appears to be:
    - Find all 8 positions
    - For each pair of 8s, if they're aligned horizontally/vertically:
      - Fill interior with 4s
      - Mark midpoint(s) with 7 where applicable
    """
    h, w = grid_in.shape

    # Background value (most common excluding anchors)
    non_anchors = [grid_in[r,c] for r in range(h) for c in range(w) 
                   if grid_in[r,c] not in [1,2,6,8]]
    background = max(set(non_anchors), key=non_anchors.count)

    # Create result grid initialized with background
    result = [[background]*w for _ in range(h)]

    # Keep anchor values in place
    for r in range(h):
        for c in range(w):
            v = grid_in[r,c]
            if v in [1,2,6,8]:
