    def is_between_horizontal(pt_r, pt_c, c1, c2):
        """Check if point column is strictly between c1 and c2."""
        return min(c1, c2) < pt_c < max(c1, c2)

    def is_between_vertical(pt_r, pt_c, r1, r2):
        """Check if point row is strictly between r1 and r2."""
        return min(r1, r2) < pt_r < max(r1, r2)

    def is_midpoint_between_two_8s(r, c, e8s):
        """Check if this cell is an exact midpoint between two 8s."""
        for i in range(len(e8s)):
            for j in range(i+1, len(e8s)):
                r1, c1 = e8s[i]
                r2, c2 = e8s[j]

                # Check horizontal midpoint
                if r1 == r2 == r and (c1 + c2) // 2 == c:
                    return True, 'horizontal'

                # Check vertical midpoint  
                if c1 == c2 == c and (r1 + r2) // 2 == r:
                    return True, 'vertical'

        return False, None

    # Apply horizontal fills between 8-pairs
    for r in range(h):
        row_eights = [(c, grid_in[r][c]) for c in range(w) if grid_in[r][c] == 8]

        for i in range(len(row_eights)):
            for j in range(i+1, len(row_eights)):
                c1, _ = row_eights[i]
                c2, _ = row_eights[j]

                # Check if there's space between them
                if c2 > c1 + 1:
                    # Fill interior (exclusive of endpoints and 8 positions)
                    for c in range(c1+1, c2):
                        if grid_in[r][c] != 8:  # Skip other special values
                            result[r][c] = 4

        # Handle midpoints that should be 7
        for c in range(1, w-1):
            if is_midpoint_between_two_8s(r, c, eights)[0]:
                result[r][c] = 7

    # Apply vertical fills between 8-pairs
    for c in range(w):
        col_eights = [(r, grid_in[r][c]) for r in range(h) if grid_in[r][c] == 8]

        for i in range(len(col_eights)):
            for j in range(i+1, len(col_eights)):
                r1, _ = col_eights[i]
                r2, _ = col_eights[j]

                if r2 > r1 + 1:
                    # Fill interior
                    for r in range(r1+1, r2):
                        if grid_in[r][c] != 8:
